contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // test parameters:
    // uint sendAmount: Ether amount forwarded to getTokens (will be forwarded as value)
    // (Note: getTokens ignores msg.value in logic, but contract has receive that calls getTokens on payable)
    function run(uint sendAmount) public payable {
        require(address(this).balance >= sendAmount);

        // Read observables before the call
        uint beforeCallerBalance = c.balanceOf(address(this));
        uint beforeTotalDistributed = c.totalDistributed();
        uint beforeTotalRemaining = c.totalRemaining();
        bool beforeBlacklist = c.blacklist(address(this));

        // Ensure distribution not finished to allow getTokens to proceed unless it reverts
        // We don't call finishDistribution; just attempt getTokens and capture revert
        bool didRevert;
        try c.getTokens{value: sendAmount}() {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // Read observables after the call
        uint afterCallerBalance = c.balanceOf(address(this));
        uint afterTotalDistributed = c.totalDistributed();
        uint afterTotalRemaining = c.totalRemaining();
        bool afterBlacklist = c.blacklist(address(this));

        // General invariant to assert:
        // If the call did not revert, then the increase in caller balance equals the increase in totalDistributed,
        // the decrease in totalRemaining equals that same amount, and if any tokens were given (>0) caller becomes blacklisted.
        // If the call reverted, none of those changed (no increase in balances or totals, blacklist unchanged).
        assert(
            // Case: reverted -> no observable changes
            (didRevert && afterCallerBalance == beforeCallerBalance && afterTotalDistributed == beforeTotalDistributed && afterTotalRemaining == beforeTotalRemaining && afterBlacklist == beforeBlacklist)
            ||
            // Case: succeeded -> deltas are consistent
            (!didRevert && (
                // compute deltas
                (afterCallerBalance >= beforeCallerBalance) &&
                (afterTotalDistributed >= beforeTotalDistributed) &&
                (beforeTotalRemaining >= afterTotalRemaining) &&
                // increase in caller balance equals increase in totalDistributed
                ((afterCallerBalance - beforeCallerBalance) == (afterTotalDistributed - beforeTotalDistributed)) &&
                // decrease in totalRemaining equals same amount
                ((beforeTotalRemaining - afterTotalRemaining) == (afterTotalDistributed - beforeTotalDistributed)) &&
                // if any tokens were given then caller is blacklisted afterwards
                (((afterCallerBalance - beforeCallerBalance) > 0) ? (afterBlacklist == true) : (afterBlacklist == beforeBlacklist))
            ))
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test parameters: sender (we use this contract as msg.sender to c), recipient, amount
    function run(address recipient, uint256 amount) public payable {
        require(recipient != address(0));

        // Ensure this contract has some tokens to transfer: use c.distr via getTokens if distribution still allowed.
        // Try to obtain tokens by calling c.getTokens() if possible. We must provide Ether 0 (function is payable but uses distribution value not price).
        bool gotTokens = false;
        // read pre-state
        uint256 beforeTotalSupply = c.totalSupply();
        uint256 beforeSenderBalance = c.balanceOf(address(this));
        uint256 beforeRecipientBalance = c.balanceOf(recipient);

        // Attempt to call transfer; but transfer will revert if amount > balance or payload size check fails.
        // To make a meaningful test, we first try to call getTokens to increase this contract's balance, ignoring revert.
        try c.getTokens{value: 0}() {
            // ignore
        } catch {
            // ignore
        }

        // Refresh balances after possible distribution
        uint256 midSenderBalance = c.balanceOf(address(this));
        uint256 midRecipientBalance = c.balanceOf(recipient);

        // Decide transfer amount: use provided amount. Attempt transfer and capture revert
        bool transferReverted;
        try c.transfer(recipient, amount) {
            transferReverted = false;
        } catch {
            transferReverted = true;
        }

        uint256 afterTotalSupply = c.totalSupply();
        uint256 afterSenderBalance = c.balanceOf(address(this));
        uint256 afterRecipientBalance = c.balanceOf(recipient);

        // General invariant: successful ERC20 transfer should not change totalSupply and the sum of sender+recipient balances
        // If transfer reverted, we cannot assert effects; so assert that either transfer reverted OR the invariant holds.
        assert(transferReverted || (afterTotalSupply == beforeTotalSupply + (midSenderBalance - beforeSenderBalance) - (midSenderBalance - beforeSenderBalance) /*no-op to use beforeTotalSupply*/ &&
               // sum before the transfer is midSenderBalance + midRecipientBalance, sum after is afterSenderBalance + afterRecipientBalance
               (afterSenderBalance + afterRecipientBalance == midSenderBalance + midRecipientBalance)));
    }

    // Allow receiving Ether if needed
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test: attempt to transfer `amount` from this contract to `to`.
    function run(address to, uint256 amount) public payable {
        require(to != address(0));

        // Read balances and totalSupply before any state-changing call
        uint256 beforeTotalSupply = c.totalSupply();
        uint256 beforeSender = c.balanceOf(address(this));
        uint256 beforeRecipient = c.balanceOf(to);

        // Attempt the transfer and record whether it reverted
        bool reverted;
        try c.transfer(to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint256 afterTotalSupply = c.totalSupply();
        uint256 afterSender = c.balanceOf(address(this));
        uint256 afterRecipient = c.balanceOf(to);

        // Assert general rule: if transfer succeeded then totalSupply unchanged and sender+recipient balances preserved
        assert(reverted || (afterTotalSupply == beforeTotalSupply && (afterSender + afterRecipient) == (beforeSender + beforeRecipient)));
    }

    receive() external payable {}
}

